#!/usr/bin/env bash
set +e
ADM="$(docker exec nyv-gateway printenv DATABASE_URL_ADMIN 2>/dev/null)"
ADM="${ADM%\"}"; ADM="${ADM#\"}"
ADM="$(echo "$ADM" | sed -E 's/sslmode=no-verify/sslmode=require/; s/sslmode=verify-full/sslmode=require/')"
SQL="$(echo '' | base64 -d)"
docker run --rm --network host -e PGURL="$ADM" -e SQL="$SQL" postgres:16-alpine   sh -c 'psql "$PGURL" -v ON_ERROR_STOP=1 -c "$SQL"' 2>&1 | tail -12
echo "=== verify nv_app can read the view ==="
APP="$(docker exec nyv-gateway printenv DATABASE_URL 2>/dev/null)"; APP="${APP%\"}"; APP="${APP#\"}"
APP="$(echo "$APP" | sed -E 's/sslmode=no-verify/sslmode=require/; s/sslmode=verify-full/sslmode=require/')"
docker run --rm --network host -e PGURL="$APP" postgres:16-alpine   sh -c 'psql "$PGURL" -At -F "|" -c "SELECT '"'"'app_view_read'"'"', count(*), COALESCE(SUM(input_tokens+output_tokens),0) FROM public.nv_ai_activity;"' 2>&1
